package android.widget;
public class MultiAutoCompleteTextView extends AutoCompleteTextView { public interface Tokenizer { int findTokenStart(CharSequence text,int cursor); int findTokenEnd(CharSequence text,int cursor); CharSequence terminateToken(CharSequence text); } private Tokenizer tokenizer; public MultiAutoCompleteTextView(android.content.Context c) { super(c); } public MultiAutoCompleteTextView(android.content.Context c,android.util.AttributeSet a) { super(c,a); } public MultiAutoCompleteTextView(android.content.Context c,android.util.AttributeSet a,int s) { super(c,a,s); } public MultiAutoCompleteTextView(android.content.Context c,android.util.AttributeSet a,int s,int r) { super(c,a,s,r); } public void setTokenizer(Tokenizer t) { tokenizer=t; } }
